using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "CrypticHourglassAction", menuName = "Data/Battle/Battle Actions/Sothis/CrypticHourglass Action")]
public class CrypticHourglassAction : BattleAction
{
	[Header("Effect")]
	[SerializeField]
	protected DefaultEffectAction hourglassMasteryAction;

	[SerializeField]
	protected DefaultEffectAction sandsOfTimeAction;

	[SerializeField]
	private int sandsOfTimeAmount;

	public DefaultEffectAction HourglassMasteryAction => hourglassMasteryAction;

	public DefaultEffectAction SandsOfTimeAction => sandsOfTimeAction;

	public int SandsOfTimeAmount => sandsOfTimeAmount;

	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		if (ReferenceSingleton<BattleHandler>.Instance.PlayerGameObject.GetComponent<CorruptionStats>().CurrentCorruption == 6f)
		{
			hourglassMasteryAction.CastTargetAmount(target, amount, source);
		}
		else
		{
			sandsOfTimeAction.CastTargetAmount(target, sandsOfTimeAmount, source);
		}
	}
}
